const math = {};
math.getUniquePermutation = getUniquePermutation;
math.getUniqueCombination = getUniqueCombination;

function getUniquePermutation(inputSet, k) {
    var getAllPermutations = function(selection) {
      var permutations = [];
      var swap = function(a, i, j) {
        var arr = a.split("-");
        var temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
        return arr.join("-");
      };
      var permute = function(str, l, r, p) {
        if (l == r) {
          p.push(str);
        } else {
          for (var i = l; i <= r; i++) {
            str = swap(str, l, i);
            permute(str, l + 1, r, p);
            str = swap(str, l, i);
          }
        }
      };
      permute(selection, 0, k - 1, permutations);
      return permutations;
    };
  
    var uniquePermutations = [];
    getUniqueCombination(inputSet, k).forEach(function(uniqueCombination) {
      getAllPermutations(uniqueCombination.join('-')).forEach(function(sel) {
        uniquePermutations.push(sel);
      });
    });
    return uniquePermutations;
  }
  
  function getUniqueCombination(set, _k) {
    var i;
    var j;
    var combs;
    var head;
    var tailcombs;
  
    if (_k > set.length || _k <= 0) {
      return [];
    }
    if (_k == set.length) {
      return [set];
    }
  
    if (_k == 1) {
      combs = [];
      for (i = 0; i < set.length; i++) {
        combs.push([set[i]]);
      }
      return combs;
    }
  
    combs = [];
    for (i = 0; i < set.length - _k + 1; i++) {
      head = set.slice(i, i + 1);
      tailcombs = getUniqueCombination(set.slice(i + 1), _k - 1);
      for (j = 0; j < tailcombs.length; j++) {
        combs.push(head.concat(tailcombs[j]));
      }
    }
    return combs;
  }   




